quests[31312] = { id = 31312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Map", description = "The old, faded leather is falling apart, but still legible.\n\nScrawled on it is some kind of map, and the following lines:\n\n\nDeep in the valley where four winds blow,\nThe maiden laughs behind her golden fan.\nAt the feet of her ancestors' stair,\nShe whispers secrets into the echoing dark.", completion = "Whoa! I think you found it, {name}! You found the map to Old Man Thistle treasure!", objectives = "Show the map to Fish Fellreed at Cattail Lake or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31313] = { id = 31313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just A Folk Story", description = "What!?! This don't make any sense! <Fish's face falls.>\n\nWhat's this mumber jumber about a maiden and an ancestor and a buncha stairs?\n\nI can't make any reason outta this, can you?\n\nWell, there are lotsa folks 'round here who're much older than you and me, {name}.\n\nCan you go talk to the folks in Halfhill? I betcha they might know somethin'!", completion = "Of course! It makes perfect sense. So the location of the treasure must be where the lake meets the mountains!", objectives = "Speak to Grainsorter Pei, Stonecarver Mac, Mama Min, and Old Man Whitewhiskers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31315] = { id = 31315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heartland Legacy", description = "At the very bottom of the treasure chest, you find a stack of scrolls and a soft leather sack with seeds.\n\nUnrolling the scrolls, you see they contain detailed farming notes, drawings of plants, numbers and calculations, locations of nearby water springs, and countless other snippets.\n\nThere might be someone at the Tillers Union who would like to see this.", progress = "What do you have there?", completion = "Ah yes, I know the story of Old Man Thistle quite well, {race}.\n\nThere are all sorts of crazy tales about his quest for treasure.\n\nBut the truth of the matter is that he was a bit of a recluse, a bit eccentric, and an excellent farmer.\n\nAs he grew near the end of his life, he retreated up into the mountains and was never seen again.\n\nHe was just a man, and it seems that you have found his legacy.\n\nBut don't tell Fish the truth. Some stories are best left tall in the telling.", objectives = "Take Old Man Thistle's Almanac to Seedkeeper Shing Sing at Halfhill in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31316] = { id = 31316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Julia, The Pet Tamer", description = "I can tell you have been honing your pet battle skills, {name}.  I think it's time for you to take on a real challenge.\n\nJulia Stevens can be found at the Maclure Vineyards south of Stormwind.  She is an up and coming wild pet tamer and I think it's time you faced her in battle!", progress = "How is your team coming along? I have two snakes so far!", completion = "You're better with those pets than I thought!", objectives = "Defeat Julia Stevens in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31317] = { id = 31317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Found Entrance" }
quests[31318] = { id = 31318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Found Treasure" }
quests[31319] = { id = 31319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Response", description = "Your companions have made themselves at home in our land, and brought with them a dangerous conflict.\n\nThe full extent of their destruction here we cannot yet know. Already it is... unspeakable.\n\nNevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care.\n\nThese fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.", completion = "My thoughts will be with your fallen companions, traveler.\n\nMay their wounds mend well.", objectives = "Use Cho's Fireworks near Admiral Taylor, Mishka and Sully.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31320] = { id = 31320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buy A Fish A Drink?", description = "Heeeey buddy, how'sh it goin'? You wanna buy a jinyu a drink?", progress = "Thirsty...", completion = "Thanksh, buddy.", objectives = "Bring 1 Four Wind Soju to Jogu the Drunk. Four Wind Soju can be purchased from most bartenders in Pandaria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31321] = { id = 31321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buy A Fish A Round?", description = "Heeeey it's my friend, the {race}!\n\nI guesh you've seen me hanging 'round, but I should 'splain that I'm not drunk.\n\nI mean, look at me now! Shober as a freshwater fish!\n\nSure I like to drown my sorrowsh in some good brew now and then, but you can't inebriate a jinyu! Might as well try to drown a fish!\n\nNo, the brewsh make me shleepy, and when I shleep, I have vishions of the future.\n\n\n\nThe shtronger the brew, the more potent my dreamsh! If you bring me a drink, I'll owe you one.", progress = "What do you mean I talk like I'm drunk? Thish ish how I shpeak!", completion = "Oooh, this is the shtuff.", objectives = "Bring 5 Pandaren Plum Wine to Jogu the Drunk. Pandaren Plum Wine can be purchased from most bartenders in Pandaria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31322] = { id = 31322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buy A Fish A Keg?", description = "My dreams grow dim recently, {race}.\n\nI need something powerful to kick myshelf back into gear!\n\nI heard there'sh a delishush drink that folksh are making nowadays.\n\nIt'sh called Jade Witch Brew.\n\nI'd sure like to taste some.", progress = "Any luck?", completion = "Oooh, that'sh got quite the kick! I'm growing shleepy...", objectives = "Bring 10 Jade Witch Brew to Jogu the Drunk. Jade Witch Brew can be made using the cooking profession.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31323] = { id = 31323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buy A Fish A Brewery?", description = "All right, {name}, in order to continue my vishions, I must now have my own brewery.\n\n...\n\nJust kidding! You should have sheen your own face! Hilarioush... hic!\n\nAnyway, I heard of a new drink that is unlike any other, and I would like a tashte.\n\nHave you heard of the Mad Brewer'sh Breakfasht? If you can bring me some of thish shtuff, you will be my friend for life.", progress = "Have you tried it?", completion = "Thank you, {name}! I will be shaving these for a rainy day... hic!", objectives = "Bring 20 Mad Brewer's Breakfast to Jogu the Drunk. Mad Brewer's Breakfasts can be made using the cooking profession.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31324] = { id = 31324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Family Secrets", description = "Our secret recipes! I was gathering them up. But then... hozen?\n\n<Auntie looks very confused.>\n\nHow is Gao to brew anything? He needs those recipes or disaster is sure to strike!", progress = "Well, hello!", completion = "Ho ho, what's this?\n\n<Uncle Gao jiggles his fat brew belly at the sight of the family's recipes.>\n\nOoh, I knew I was adding too much corn!", objectives = "Collect 5 Stormstout Secrets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31325] = { id = 31325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Very Nice Necklace", description = "The beautiful necklace is only partly smudged by dirty hozen hands.\n\nThere's only one person in the Valley who would own such a beautiful piece of jewelry.", completion = "Oh my, this is my favorite necklace! I didn't even know it was missing! Thank you, {name}.", objectives = "Bring the necklace to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31326] = { id = 31326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tina's Tasteful Tiara", description = "It's a dazzling diamond tiara. Who in the valley would be wealthy enough to own such a piece of jewelry?\n\nWhoever it is, they might be willing to give a nice reward.", completion = "Oh, my tiara! It was missing, but wherever did you find it?", objectives = "Bring the Tasteful Tiara to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31327] = { id = 31327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble Brewing", description = "With the brewery infested by hozen and... and who knows what else, I'm sure that the brewers are in trouble.\n\nWould you mind helping me find out what's going on, my friend?", completion = "A giant creature made of brew?! Who could have imagined such a thing?\n\nYou have my thanks for saving Gao from his own misguided brewing experiments.", objectives = "Kill Yan-Zhu the Uncasked.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31328] = { id = 31328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exquisite Earring", description = "You unhook the earring off the furry creature's ear. It looks like he was having some fun wearing the dangly hoop. TOO much fun.\n\nPerhaps the owner of this dainty bauble would like to see it returned. You don't have to tell her where you found it... or who was wearing it.", completion = "Oh my earring! Why, it matches the one I'm wearing today!\n\n<Tina hooks the earring onto her ear.>\n\nThank you, {name}!", objectives = "Bring the Exquisite Earring to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31329] = { id = 31329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Beautiful Brooch", description = "It is a very old, antique brooch with very detailed molding and filigree worked into the edges. It looks very valuable.\n\nThere's only one person who keeps losing jewelry to furry hooligans, and she would probably want to see this heirloom returned.", completion = "My grandmother's brooch! Oh, thank you for finding this! It's a family treasure.", objectives = "Bring the Beautiful Brooch to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31331] = { id = 31331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Figuring out how to make quests", description = "Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.", sourceObjective = "Make a breadcrumb quest.", sourceObjectiveStatus = "unverified-source-field" }
quests[31332] = { id = 31332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lesson 1: Sliced Peaches", description = "I'm excited to start my training. We start with sliced peaches, right?", progress = "I really want to be a chef, but the other kids already started a couple of months ago. There's no way I can catch up without your help.", completion = "Here it is!  How did I do?", objectives = "Obtain a 5 Pandaren Peaches for Nomi's cooking lesson.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31333] = { id = 31333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lesson 2: Instant Noodles", description = "Instant noodles aren't that hard to cook, right?", progress = "It's so easy to overcook the noodles!", completion = "Here it is!  How did I do?", objectives = "Obtain 5 Instant Noodles for Nomi's Lesson.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31334] = { id = 31334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lesson 3: Toasted Fish Jerky", description = "Cooking is harder than I thought.  It's so easy to burn things.", progress = "I hope I don't burn myself.  Eep.", completion = "Here it is!  How did I do?", objectives = "Obtain 5 Golden Carp for Nomi's Lesson.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31335] = { id = 31335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lesson 4: Dried Needle Mushrooms", description = "I'm not very fond of mushrooms... but I'll do my best to learn.", progress = "Ick.", completion = "Here it is!  How did I do?", objectives = "Obtain 5 Needle Mushrooms for Nomi's Lesson.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31336] = { id = 31336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lesson 5: Pounded Rice Cake", description = "I love rice cakes.  I'll do my best to make good ones!", progress = "I can't wait to see how they turn out!", completion = "Here it is!  How did I do?", objectives = "Obtain 5 Rice for Nomi's Lesson.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31337] = { id = 31337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Token of Appreciation", description = "Thanks for checking to make sure I'm doing well!  I've been able to help out the Ironpaws today, and they said I could give this to you.", sourceObjective = "Receive Nomi's gift.", completion = "You're my favorite teacher ever.", sourceObjectiveStatus = "unverified-source-field" }
quests[31338] = { id = 31338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Sheepie", description = "Chee Chee's prize sheep, Sheepie, is missing!\n\nThat bad sheep is always wandering off the farm.\n\nStupid sheep! I looked everywhere and couldn't find him.\n\nCan you help me, {race}?", progress = "Did you find my Sheepie? Oh, I was so worried.", completion = "Oh, you found him! Thank you!", objectives = "Find Sheepie and return him to Chee Chee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31339] = { id = 31339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Sheepie... Again", description = "That stupid sheep! He wandered off again!\n\nCan you find him for me again?", progress = "Oh, poor Sheepie. He's probably so scared and alone...", completion = "Sheepie, you make me so worried! Bad sheep! Chee Chee was so worried about you!", objectives = "Find Sheepie and bring him back to Chee Chee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31340] = { id = 31340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Sheepie...", description = "Sigh... you guessed it... Sheepie is gone... AGAIN.\n\nStupid sheep! Gives me so much trouble!\n\nI hate to ask you again, but I promise this will be the last time.\n\nCan you find him for me?", completion = "What? Sheepie is... gone?\n\n<Chee Chee's lip begins to quiver.>", objectives = "Find Sheepie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31341] = { id = 31341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wolf In Sheep's Clothing", description = "AAAIIIIEEUUGGHHHH!!!! This is the last straw!\n\nThose stupid hozen on the mountain killed my SHEEPIE!\n\nI know exactly who did this, and it is time for REVENGE.\n\nIf you are willing to help me, take this old sheepskin.\n\nUse it to disguise yourself anywhere on the mountain to the north, wait for that little dooker Krungko to come out of hiding, and then break his bones!", completion = "Thank you, {name}. It will not bring my Sheepie back, but at least this way, no more sheep will be lost.", objectives = "Use the old sheepskin anywhere in the Skyrange or Kunzen Village, then kill Krungko.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31342] = { id = 31342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to Respect Lies in Violence", description = "You have proven yourself in battle.\n\nStill, if you would aid us further, I must ask something else of you.\n\nThe Sha of Violence awaits beyond within the Sealed Chambers. Destroy it if you would earn my respect.", completion = "You have defeated the Sha of Violence and saved the monastery. You have my respect.\n\nPerhaps we were wrong about your people, {name}.", objectives = "Kill the Sha of Violence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31343] = { id = 31343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kovok Tracking" }
quests[31344] = { id = 31344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Chee Chee Exalted" }
