quests[31353] = { id = 31353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Tina Mudclaw Exalted" }
quests[31354] = { id = 31354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazu's Bounty", completion = "Hey there!\n\nOh, I'm fine. I've had worse spills than that after a night at the Chum Bucket.\n\nBut would you look at this thing? I spotted it peeking out of the sea floor when I went under - Jiao must have dredged it up while he was thrashing around.\n\nNot really sure what to do with it, but it looks valuable. Seeing as how you pretty much saved all our hides, I think we owe you this catch.", objectives = "Speak with Master Angler Ju Lien in Soggy's Gamble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31355] = { id = 31355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Jade's Purity", description = "{class}, will you aid us?\n\nThe temple's purity has been jeopardized. Even now the three masters struggle against their doubts.\n\nPlease, I beg you, head in and help Wise Mari, Liu Flameheart, and Lorewalker Stonestep in their fight against the sha.", progress = "Please, you must assist those within before they succumb to their doubts.", completion = "While I am sad to hear the fates of Wise Mari and Priestess Flameheart, you have my heartfelt thanks.", objectives = "Assist Wise Mari, Liu Flameheart, and Lorewalker Stonestep with their sha problems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31356] = { id = 31356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Doubts, Deep Wisdom", description = "There is an ancient pandaren saying that states, \"With deep doubts comes deep wisdom.\"\n\nThe Sha of Doubt has infested the Heart of Jade within the temple. It must be destroyed.\n\nI dare say that you are about to become all the wiser, {class}.", progress = "The Sha of Doubt must be destroyed, {name}, or we are all lost.", completion = "I never doubted you. Funny though, you don't look any wiser.\n\n<The master winks.>", objectives = "Kill the Sha of Doubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31357] = { id = 31357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Four Kings", description = "The mogu have reawakened and are a threat to all of Pandaria. They are on the cusp of becoming even more dangerous.\n\nThere are four great mogu kings of legend: Zian of the Endless Shadow, Meng the Demented, Qiang the Merciless, and Subetai the Swift. Four artifacts of these kings are secreted away in the Vault of Kings Past, below.\n\nYou must retrieve these relics before the mogu discover them and become unstoppable.", progress = "We must retrieve the lantern, balance, scroll, and bow before Xin and his clans uncover them.", completion = "I will find a better hiding place for the four relics.\n\nPandaria is indebted to you, {name}.", objectives = "Collect the Lantern of the Sorcerer King, Mad King Meng's Balance, Qiang's \"The Science of War\", and Subetai's Bow of the Swift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31359] = { id = 31359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kunchong Whisperer", description = "To really connect with Kovok you need to challenge him mentally and physically. You must respect his strength and intelligence; only then will he allow you to really train him.\n\nThe muckscale tribe may provide an adequate test of his abilities and with you there he shouldn't be in danger.\n\nAdditionally, this will allow us to decrease their numbers in the Briny Muck.", completion = "I am most impressed with your progress, Wakener. Kovok's training is coming along nicely and he seems to be fond of you.\n\nI have no doubt that you are the best choice to assist me in training him.", objectives = "Kill Oracle Hiss'ir and 10 Muckscale tribe members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31360] = { id = 31360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Lesson for the Master", description = "A new king of the mogu has arisen: Xin the Weaponmaster.\n\nHe single-handedly subjugated the mogu clans, and now they and their new leaders vie for his favor.\n\nI've never seen or read of any who are his equal in battle. Do not underestimate Xin, {name}.\n\nOur fate rests in your hands.", progress = "The king of the mogu must die.\n\nThough another will eventually rise, none are as deadly as Xin the Weaponmaster.", completion = "Truly a fight for the ages.\n\nI'm glad that you're on our side, {name}.", objectives = "Kill Xin the Weaponmaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31362] = { id = 31362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Piece of the Puzzle", description = "I must say, {name}, despite their skirmishes with the hozen, I've never seen the jinyu so militant.\n\nThis troubles me. We must discuss it another time, however. I have come to ask for your assistance.\n\nThe fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor would have us remember.\n\nMy meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.", progress = "Yes, {class}?", completion = "<Lorewalker Cho shudders, in spite of himself.>\n\nThe legends... they're true!", objectives = "Use Cho's Heirloom at Cho's Family Shrine on Serpent's Overlook.\n\nSpeak with Mishi for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31363] = { id = 31363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lighting the Way", description = "We need reinforcements! Someone has to fight through and light the signal flame.\n\nIt's all up to you, {class}. No pressure or anything.", progress = "{name}, you need to get out there and signal the reinforcements!", completion = "Outstanding, {name}. Your timing couldn't have been better!", objectives = "Light the Signal Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31364] = { id = 31364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's a Big Bug!", description = "The mantid have something they call Raigonn. It's a giant bug they're using to bust down the wall's gates!\n\nLet's keep that thing from getting into the vale!", progress = "You need to bring that thing down before it busts through the final gate!", completion = "If I didn't see it with my own eyes, I wouldn't have believed it.\n\nGreat job, {name}!", objectives = "Kill Raigonn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31365] = { id = 31365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Somewhere Inside", description = "I sent a dozen of my best men ahead to infiltrate the mantid siege.\n\nNone have returned.\n\nSince you are taking the fight directly to the mantid, you will be in a position to free any who had the misfortune to be captured.\n\nYou will do this?", progress = "My men are being held somewhere amongst the mantid siege.", completion = "Thirteen thanks I give to you; twelve for those you rescued and my own as well.\n\nHere's something else I give to you in gratitude.", objectives = "Rescue 12 Shado-Pan Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31366] = { id = 31366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Down the Wing Leader", description = "The mantid have lain siege to Niuzao Temple.\n\nEven now, Wing Leader Ner'onok and his forces work to cross the final chasm.\n\nYou must stop him before they reconstruct that bridge.", progress = "Hurry, {class}, the construction of the mantid bridge nears completion.", completion = "The wing leader lies dead and the siege is broken.\n\nYou've saved the temple, {name}.", objectives = "Kill Wing Leader Ner'onok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31367] = { id = 31367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lorewalkers", description = "So you are interested in learning more of the lore of this land?\n\nVery well! You should speak to Lorewalker Cho at the Seat of Knowledge.\n\nHe can be found in the room above the entrance to the Mogu'shan Palace. Speak with Mishi for a ride.", progress = "Welcome, traveler.", completion = "Ah yes, I can see by your face that you are an eager seeker of stories. You have come to the right place.", objectives = "Speak to Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31368] = { id = 31368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lorewalkers", description = "So you are interested in learning more of the lore of this land?\n\nVery well! You should speak to Lorewalker Cho at the Seat of Knowledge.\n\nHe can be found in the room above the entrance to the Mogu'shan Palace. Speak with Mishi for a ride.", progress = "Welcome, traveler.", completion = "Ah yes, I can see by your face that you are an eager seeker of stories. You have come to the right place.", objectives = "Speak to Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31369] = { id = 31369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Anglers", description = "If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to Haito at the Anglers Wharf in Krasarang Wilds.\n\nI'm sure he'd love to show you a thing or two about reeling!", completion = "You ready to catch some FISH?", objectives = "Speak to Fisherman Haito at the Anglers Wharf in the Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31370] = { id = 31370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Anglers", description = "If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to Haito at the Anglers Wharf in Krasarang Wilds.\n\nI'm sure he'd love to show you a thing or two about reeling!", completion = "You ready to catch some FISH?", objectives = "Speak to Fisherman Haito at the Anglers Wharf in the Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31371] = { id = 31371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Player Has Completed One Anglers Daily" }
quests[31372] = { id = 31372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tillers", description = "The Tillers do their business at Halfhill in the Valley of the Four Winds.\n\nIf you're interested in getting started, I hear there's a new farmer in town by the name of Farmer Yoon.\n\nI betcha he'll be looking for help.", completion = "You arrived just in time!", objectives = "Speak to Farmer Yoon at Sunsong Ranch in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31373] = { id = 31373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Order of the Cloud Serpent", description = "The Order of the Cloud Serpent is always searching for talented riders.\n\nIf you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest.\n\nI wish you luck, {race}.", completion = "Ah, have you come to join the Order?", objectives = "Speak to Instructor Skythorn at The Arboretum in The Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31374] = { id = 31374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tillers", description = "The Tillers do their business at Halfhill in the Valley of the Four Winds.\n\nIf you're interested in getting started, I hear there's a new farmer in town by the name of Farmer Yoon.\n\nI betcha he'll be looking for help.", completion = "You arrived just in time!", objectives = "Speak to Farmer Yoon at Sunsong Ranch in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31375] = { id = 31375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Order of the Cloud Serpent", description = "The Order of the Cloud Serpent is always searching for talented riders.\n\nIf you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest.\n\nI wish you luck, {race}.", completion = "Ah, have you come to join the Order?", objectives = "Speak to Instructor Skythorn at The Arboretum in The Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31376] = { id = 31376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack At The Temple of the Jade Serpent", description = "Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests beseech us for aid.\n\nThey hold the sha in check, but just barely.\n\nYou may be able to turn the tide, {class}.", completion = "You've arrived just in time, {class}.", objectives = "Speak to Elder Sage Tai-Feng at the Jade Temple Grounds in The Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31377] = { id = 31377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack At The Temple of the Jade Serpent", description = "Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests beseech us for aid.\n\nThey hold the sha in check, but just barely.\n\nYou may be able to turn the tide, {class}.", completion = "You've arrived just in time, {class}.", objectives = "Speak to Elder Sage Tai-Feng at the Jade Temple Grounds in The Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31378] = { id = 31378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge At The Temple of the Red Crane", description = "The Temple of the Red Crane still reels from the aftermath of the sha's presence, and has only recently gathered to rebuild and retrain its warriors.\n\nIf you wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.", completion = "Welcome, {class}.", objectives = "Speak to Thelonius at the Cradle of Chi-Ji in the Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31379] = { id = 31379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge At The Temple of the Red Crane", description = "The Temple of the Red Crane still reels from the aftermath of the sha's presence, and has only recently gathered to rebuild and retrain its warriors.\n\nIf you wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.", completion = "Welcome, {class}.", objectives = "Speak to Thelonius at the Cradle of Chi-Ji in the Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31380] = { id = 31380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial At The Temple of the White Tiger", description = "Xuen, the great Celestial of the North, seeks the greatest champions in the land.\n\nToday, he holds trials of battle at his temple in Kun-Lai Summit.\n\nIf you wish to test yourself against skilled fighters from all across Pandaria, then go to him and enter the challenger's ring!", completion = "So you wish to test your skills? Very good, {race}.", objectives = "Speak to Xuen at the Temple of the White Tiger in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31381] = { id = 31381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial At The Temple of the White Tiger", description = "Xuen, the great Celestial of the North, seeks the greatest champions in the land.\n\nToday, he holds trials of battle at his temple in Kun-Lai Summit.\n\nIf you wish to test yourself against skilled fighters from all across Pandaria, then go to him and enter the challenger's ring!", completion = "So you wish to test your skills? Very good, {race}.", objectives = "Speak to Xuen at the Temple of the White Tiger in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31382] = { id = 31382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense At Niuzao Temple", description = "Niuzao Temple, far to the west, is under attack by the mantid.\n\nThe great Celestial holds them back for now, but he cannot stand alone forever.\n\nGo and help the defenders, {class}. The Temple must not fall!", completion = "Well met, {class}! We need your help.", objectives = "Speak to Ogo the Elder at Niuzao Temple in the Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31383] = { id = 31383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense At Niuzao Temple", description = "Niuzao Temple, far to the west, is under attack by the mantid.\n\nThe great Celestial holds them back for now, but he cannot stand alone forever.\n\nGo and help the defenders, {class}. The Temple must not fall!", completion = "Well met, {class}! We need your help.", objectives = "Speak to Ogo the Elder at Niuzao Temple in the Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31384] = { id = 31384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golden Lotus", description = "The Golden Lotus have guarded the Vale for centuries, keeping it safe and hidden from harm.\n\nRecent events have unleashed terrible horrors upon our sacred vale, but allies of the Golden Lotus still stand against them, attempting to bring peace.\n\nIf you wish to help, you had best join them at the Setting Sun Garrison.", completion = "Well met, {race}. You look capable. Glad to know we have a decent {class} on our side.", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31385] = { id = 31385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golden Lotus", description = "The Golden Lotus have guarded the Vale for centuries, keeping it safe and hidden from harm.\n\nRecent events have unleashed terrible horrors upon our sacred vale, but allies of the Golden Lotus still stand against them, attempting to bring peace.\n\nIf you wish to help, you had best join them at the Setting Sun Garrison.", completion = "Well met, {race}. You look capable. Glad to know we have a decent {class} on our side.", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31386] = { id = 31386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shado-Pan Offensive", description = "We Shado-Pan have amassed our forces for the first time in many ages.\n\nThe Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to imprison it once more.\n\nHowever, our warriors are great, but our numbers too few. Help from a capable {class} may not be turned away.\n\nIf you wish to join the offensive, speak to Taran Zhu in the Townlong Steppes.", completion = "Well met, {race}.", objectives = "Speak to Taran Zhu at Longying Outpost in the Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31387] = { id = 31387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding The Shado-Pan", description = "The Shado-Pan rank among Pandaria's oldest defenders.\n\nFor years we train in our snow-capped monastery high in the Kun-Lai Summit, perfecting the martial secrets passed down by our ancestors.\n\nOur numbers may seem few, but a single Shado-Pan can be deadlier than a hundred trained soldiers.\n\nTo join the Shado-Pan order is a long journey full of hardship. If this is the path you seek, then you must first prove your worth.\n\nThere is urgent work to be done here. Help the Golden Lotus defend the Vale.", completion = "Ah yes. {name}. Your name has traveled to us from the east.\n\nWe have seen your efforts in the Vale of Eternal Blossoms. Already you have earned the esteem of the Golden Lotus.\n\nYes, we are interested to learn more about you.", objectives = "Earn Revered standing with the Golden Lotus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31388] = { id = 31388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shado-Pan Offensive", description = "We Shado-Pan have amassed our forces for the first time in many ages.\n\nThe Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to imprison it once more.\n\nHowever, our warriors are great, but our numbers too few. Help from a capable {class} may not be turned away.\n\nIf you wish to join the offensive, speak to Taran Zhu in the Townlong Steppes.", completion = "Well met, {race}.", objectives = "Speak to Taran Zhu at Longying Outpost in the Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31389] = { id = 31389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding The Shado-Pan", description = "The Shado-Pan rank among Pandaria's oldest defenders.\n\nFor years we train in our snow-capped monastery high in the Kun-Lai Summit, perfecting the martial secrets passed down by our ancestors.\n\nOur numbers may seem few, but a single Shado-Pan can be deadlier than a hundred trained soldiers.\n\nTo join the Shado-Pan order is a long journey full of hardship. If this is the path you seek, then you must first prove your worth.\n\nThere is urgent work to be done here. Help the Golden Lotus defend the Vale.", completion = "Ah yes. {name}. Your name has traveled to us from the east.\n\nWe have seen your efforts in the Vale of Eternal Blossoms. Already you have earned the esteem of the Golden Lotus.\n\nYes, we are interested to learn more about you.", objectives = "Earn Revered standing with the Golden Lotus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31390] = { id = 31390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Klaxxi", description = "The Klaxxi are only rumored to exist, far beyond the wall in the Dread Wastes.\n\nFew have ventured into that territory, and none have returned to tell the tale.\n\nIf you are set on finding these... Klaxxi... there is a small group of Shado-Pan manning the wall to the far southwest who may know more.", completion = "The Dread Wastes is a very dangerous place.", objectives = "Speak to Bowmistress Li at the Gate of the Setting Sun between the Vale of Eternal Blossoms and the Dread Wastes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31391] = { id = 31391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Klaxxi", description = "The Klaxxi are only rumored to exist, far beyond the wall in the Dread Wastes.\n\nFew have ventured into that territory, and none have returned to tell the tale.\n\nIf you are set on finding these... Klaxxi... there is a small group of Shado-Pan manning the wall to the far southwest who may know more.", completion = "The Dread Wastes is a very dangerous place.", objectives = "Speak to Bowmistress Li at the Gate of the Setting Sun between the Vale of Eternal Blossoms and the Dread Wastes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31392] = { id = 31392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of the White Tiger", description = "Have you heard the news, traveller? There's been an attack at one of our most sacred places, the Vale of Eternal Blossoms!\n\nEven now, there's a human prince within the White Tiger Temple arguing that you and the other races from beyond the mists should be allowed within.\n\nThe temple is in the northeast of Kun-Lai. Maybe you can convince the White Tiger to allow you inside?\n\nI only hope the Vale has not been utterly destroyed...", completion = "{class}, I'm glad you're here! The Pandaren tell of a legendary place, the \"Vale of Eternal Blossoms.\" It's a place of great healing, if the locals are to be believed.\n\nBetween the destruction of the Cataclysm and the horrors of this light-forsaken war, the Vale may be our best hope for healing the wounds of the world.\n\nWe need to get in there!", objectives = "Speak to Anduin Wrynn at the Temple of the White Tiger in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31393] = { id = 31393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of the White Tiger", description = "Have you heard the news, traveller? There's been an attack at one of our most sacred places, the Vale of Eternal Blossoms!\n\nEven now, there's a human prince within the White Tiger Temple arguing that you and the other races from beyond the mists should be allowed within.\n\nThe temple is in the northeast of Kun-Lai. Maybe you can convince the White Tiger to allow you inside?\n\nI only hope the Vale has not been utterly destroyed...", completion = "Hello, {class}! The human prince from Stormwind has been granted an audience with the White Tiger. He seeks to gain admittance into the Vale of Eternal Blossoms... for both the Alliance and the Horde.\n\nThe Vale is a sacred place. I believe my wife Leza saw it in a vision - it's what brought my people to Pandaria. Perhaps we will find shelter there.\n\nDo you think we will be allowed inside?", objectives = "Speak to Dezco at the Temple of the White Tiger in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31394] = { id = 31394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Celestial Experience", description = "Nobody is allowed into the Vale without the approval of the August Celestials. Xuen, The White Tiger, appears ready to listen to me.\n\nBut Taran Zhu of the Shado-Pan is reluctant to let the Alliance or Horde anywhere NEAR the Vale after all that's happened.\n\n<Anduin shakes his head.>\n\nMaybe you can help me make my case. Speak to the White Tiger on our behalf. Be careful! He may set a number of challenges before you...", progress = "Are you finished with the White Tiger's tasks?", completion = "You did it, {name}!\n\nThe White Tiger has agreed to allow us to accompany the Pandaren into the Vale of Eternal Blossoms. We can set up an Alliance outpost in there to act as our embassy with the Pandaren.", objectives = "Speak to Xuen and complete his tests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31395] = { id = 31395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Celestial Experience", description = "The human calf is arguing on our behalf. He is well-spoken; I can see why Baine Bloodhoof regards the prince so highly.\n\nStill, the argument does not go well. I am of little consequence, but you are a hero of the Horde. Perhaps you can intercede in our favor?\n\nSpeak with the White Tiger and plead our case, {race}.\n\nBe careful! He may set a number of challenges before you...", progress = "Have you passed the White Tiger's tests. {race}?", completion = "You did it, {name}!\n\nThe White Tiger has agreed to allow us to accompany the Pandaren into the Vale of Eternal Blossoms.\n\nWhere the Alliance Prince failed, a hero of the Horde prevailed.", objectives = "Speak to Xuen and pass his tests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31396] = { id = 31396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Ship's Storage" }
quests[31397] = { id = 31397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Wodin's Mantid Shanker" }
quests[31398] = { id = 31398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falling to Pieces", description = "Why would the saurok have amber? More importantly, why would Oracle Hiss'ir be so protective of it?\n\nIt is unlikely this came from the heavily guarded Zan'vess, so where did it come from?\n\nPerhaps the Klaxxi will know what to make of it.", progress = "Where did you find this?", completion = "You were wise to bring this to us. This is a piece of another paragon's encasing amber.\n\nThe damage suggests the paragon may be in trouble.\n\nI will speak with the council to decide what should be done next.", objectives = "Return the Glowing Amber to Kaz'tik the Manipulator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31399] = { id = 31399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Ancient Pandaren Mining Pick" }
