quests[31568] = { id = 31568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On The Mend", description = "Now that you have won a battle, we need to heal up your pets so they can fight another day!  Visit Esbina, our local stable master, to heal and revive your pets.", completion = "Now those look like some healthy pets, {name}.  Remember, you can heal and revive your entire collection of pets at any time by visiting a stable master.", objectives = "Heal your pets to full health by visiting Esbina the Stable Master.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31569] = { id = 31569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Got one!", description = "Great work so far, {name}!  You are going to be a pro at this pet stuff before you know it.  Now it's time to catch a pet of your own!\n\nHead back out and find a battle pet to fight, engage it in battle, and throw your trap once it's low on health.  Bring your catch back for me to see once you are finished.\n\nRemember, you need at least one pet at level 3 to use your trap!", completion = "I see... an excellent choice. You're on your way to building up a great team!\n\nRemember, any pet you can fight, you can catch, so go ahead and try to get as many as you can during your adventures.", objectives = "Catch a battle pet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31570] = { id = 31570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Got one!", description = "Great work so far, {name}!  You are going to be a pro at this pet stuff before you know it.  Now it's time to catch a pet of your own!\n\nHead back out and find a battle pet to fight, engage it in battle, and throw your trap once it's low on health.  Bring your catch back for me to see once you are finished.\n\nRemember, you need at least one pet at level 3 to use your trap!", completion = "I see... an excellent choice. You're on your way to building up a great team!\n\nRemember, any pet you can fight, you can catch, so go ahead and try to get as many as you can during your adventures.", objectives = "Catch a battle pet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
